use onklav_ui::{*,serde_json::{json,Value}};
fn step(mut input:Value)->Value{let p=weather::Place::open_meteo(40.,-80.,"Synthetic weather fixture").unwrap();let seed=input["event"]["action"]=="demo.seed";if seed{input["event"]=json!({"action":"fixture.prepare"});}let mut f=weather::controller(input,&p);if seed{let response=json!({"status":200,"text":json!({"current_units":{"time":"unixtime","temperature_2m":"°C","wind_speed_10m":"km/h"},"current":{"time":10000,"temperature_2m":0.,"wind_speed_10m":16.09344,"weather_code":0}}).to_string()});let data=weather::parse(&p,&response,10000).unwrap();f["state"]["pending_data"]=data;f["effect"]=weather::cache(f["state"]["pending_data"].clone(),f["state"]["revision"].as_u64().unwrap_or(0),"weather.stored");}f["body"].as_array_mut().unwrap().insert(0,label("demo.notice","SYNTHETIC fixture; not real weather"));if f["state"]["busy"]!=true{f["body"].as_array_mut().unwrap().push(button("demo.seed","Store synthetic weather fixture"));}f}
onklav_ui::app!(step);
